import React from "react";
import { render, fireEvent, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import ConsoleSpy from "../../lib/tests/ConsoleSpy";
import * as stories from "./Toggle.stories";
import Toggle from ".";

const { Basic, Controlled } = composeStories(stories) as any;

describe("Toggle component", () => {
  let consoleSpy = ConsoleSpy();

  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("passes through props", () => {
    render(<Toggle label="toggle" data-testid="toggle" />);
    expect(screen.getByRole("checkbox")).toHaveAttribute(
      "data-testid",
      "toggle"
    );
  });

  it("should get checked when clicking on label", () => {
    render(<Toggle label="toggle" />);
    fireEvent.click(screen.getByText("toggle"));
    expect(screen.getByRole("checkbox")).toBeChecked();
  });

  it("should work in controlled mode", () => {
    render(<Controlled />);
    fireEvent.click(screen.getByText("Option 2"));
    expect(screen.getByRole("checkbox", { name: "Option 2" })).toBeChecked();
    fireEvent.click(screen.getByText("Option 2"));
    expect(
      screen.getByRole("checkbox", { name: "Option 2" })
    ).not.toBeChecked();
  });

  it("support keyboard interactions", async () => {
    consoleSpy.log.mockRestore();
    const onChange = jest.fn();
    render(<Toggle label="toggle" onChange={onChange} />);
    const input = screen.getByRole("checkbox");
    input.focus();
    // space key
    await userEvent.keyboard("[Space]");
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(input).toBeChecked();
    // enter key
    await userEvent.keyboard("[Enter]");
    expect(onChange).toHaveBeenCalledTimes(2);
    expect(input).not.toBeChecked();
  });
});
